#!/bin/bash
# Builds the Rust core for the macOS app:
#   Frameworks/KeysteadCore.xcframework   static library (arm64 + x86_64), C header, module map
#   Keystead/Generated/keystead_ffi.swift  the Swift API, generated by UniFFI
#
# Run it once before opening the Xcode project; the project also runs it on every build.
# Linking a static library means there's no extra binary inside the app to sign.
set -euo pipefail

APP_DIR="$(cd "$(dirname "$0")/.." && pwd)"
REPO_DIR="$(cd "$APP_DIR/../.." && pwd)"
BUILD_DIR="$APP_DIR/build/core"
GENERATED_DIR="$APP_DIR/Keystead/Generated"
FRAMEWORK="$APP_DIR/Frameworks/KeysteadCore.xcframework"
TARGETS=(aarch64-apple-darwin x86_64-apple-darwin)

# Xcode runs build scripts with a minimal PATH.
export PATH="$HOME/.cargo/bin:/opt/homebrew/opt/rustup/bin:/opt/homebrew/bin:/usr/local/bin:$PATH"
# Match the app's deployment target so the linker doesn't warn about newer objects.
export MACOSX_DEPLOYMENT_TARGET=14.0

cd "$REPO_DIR"
installed="$(rustup target list --installed)"
libraries=()
built=()
for target in "${TARGETS[@]}"; do
    if grep -qx "$target" <<<"$installed"; then
        cargo build --quiet --release -p keystead-ffi --target "$target"
        libraries+=("$REPO_DIR/target/$target/release/libkeystead_ffi.a")
        built+=("$target")
    else
        echo "warning: Rust target $target isn't installed, so the app won't run on it" \
             "(rustup target add $target)" >&2
    fi
done
if [ ${#libraries[@]} -eq 0 ]; then
    echo "error: no Rust targets to build" >&2
    exit 1
fi

mkdir -p "$BUILD_DIR"
lipo -create "${libraries[@]}" -output "$BUILD_DIR/libkeystead_ffi.a.new"

# Nothing changed: leave the outputs alone so Xcode doesn't relink on every build.
if [ -d "$FRAMEWORK" ] && [ -f "$GENERATED_DIR/keystead_ffi.swift" ] \
    && cmp -s "$BUILD_DIR/libkeystead_ffi.a.new" "$BUILD_DIR/libkeystead_ffi.a" 2>/dev/null; then
    rm "$BUILD_DIR/libkeystead_ffi.a.new"
    exit 0
fi
mv "$BUILD_DIR/libkeystead_ffi.a.new" "$BUILD_DIR/libkeystead_ffi.a"

# UniFFI reads the API description embedded in the compiled library.
rm -rf "$BUILD_DIR/bindings"
cargo run --quiet -p keystead-uniffi-bindgen -- generate \
    --library "$REPO_DIR/target/${built[0]}/release/libkeystead_ffi.dylib" \
    --language swift --out-dir "$BUILD_DIR/bindings"

rm -rf "$BUILD_DIR/headers"
mkdir -p "$BUILD_DIR/headers" "$GENERATED_DIR" "$(dirname "$FRAMEWORK")"
cp "$BUILD_DIR/bindings/keystead_ffiFFI.h" "$BUILD_DIR/headers/"
cp "$BUILD_DIR/bindings/keystead_ffiFFI.modulemap" "$BUILD_DIR/headers/module.modulemap"
cp "$BUILD_DIR/bindings/keystead_ffi.swift" "$GENERATED_DIR/"

rm -rf "$FRAMEWORK"
xcodebuild -create-xcframework \
    -library "$BUILD_DIR/libkeystead_ffi.a" -headers "$BUILD_DIR/headers" \
    -output "$FRAMEWORK" >/dev/null
echo "Built KeysteadCore.xcframework ($(lipo -archs "$BUILD_DIR/libkeystead_ffi.a"))"
